def parse_coordinates(bounds: str) -> tuple[float, float]:
    """
    将bounds字符串转换为坐标点
    """
    numbers = list(map(int, re.findall(r'\d+', bounds)))

    # 检查是否提取到了4个数字
    if len(numbers) != 4:
        raise ValueError("bounds转化为坐标点失败")
    else:
        return (numbers[0] + numbers[2]) / 2, (numbers[1] + numbers[3]) / 2


def plate_province_input(plate_number: str, xml: str) -> Action:
    """车牌省份输入rpa代码"""
    province_char = plate_number[0]
    button_bounds_pattern = rf'<node[^>]*text="{province_char}"[^>]*bounds="([^"]+)"'
    button_bounds_matchs = re.findall(button_bounds_pattern, xml)
    if len(button_bounds_matchs) == 0:
        raise ValueError("未找到省份按钮")
    elif len(button_bounds_matchs) > 1:
        button_bounds = button_bounds_matchs[1]
    else:
        button_bounds = button_bounds_matchs[0]
    x, y = parse_coordinates(button_bounds)
    # return ClickAction(x=x, y=y, is_full_screen=True)
    return ClickAction(x=x, y=y)


def plate_letter_num_input(plate_number: str, xml: str) -> list[Action]:
    """车牌字母数字输入rpa代码"""
    #从xml匹配省份输入框的内容
    plate_number = plate_number.upper()
    plate_province_bounds_pattern = r'<node[^>]*text="([京津冀晋蒙辽吉黑沪苏浙皖闽赣鲁豫鄂湘粤桂琼渝川黔云藏陕甘青宁新])"[^>]*bounds="([^"]+)"'
    plate_province_bounds_match = re.search(plate_province_bounds_pattern, xml)
    assert len(plate_province_bounds_match.groups()) == 2, f"省份输入框正则匹配的个数不为2"
    province = plate_province_bounds_match.group(1) if plate_province_bounds_match else ""
    province_coord = plate_province_bounds_match.group(2) if plate_province_bounds_match else ""
    province_char = plate_number[0]  # 车牌省
    # 判断车牌省和界面省是否一致
    # if province == province_char:
        # 一致  继续输入字母数字
    actions: list[Action] = []
    for item in plate_number[1:]:
        # 点击字母数字
        button_index = NUMBER_LETTER_INDEX_MAP.get(item)
        if button_index == "":
            button_bounds_pattern = rf'<node[^>]*text="{item}"[^>]*bounds="([^"]+)"'
        else:
            button_bounds_pattern = rf'index\s*=\s*["\']{button_index}["\'].*?text\s*=\s*["\']{re.escape(item)}["\'].*?bounds\s*=\s*["\']([^"\']*)["\']'
        button_bounds_matchs = re.findall(button_bounds_pattern, xml, re.DOTALL)
        if len(button_bounds_matchs) == 0:
            raise ValueError("未找到字母数字按钮")
        elif len(button_bounds_matchs) > 1:
            button_bounds = button_bounds_matchs[1]
        else:
            button_bounds = button_bounds_matchs[0]
        x, y = parse_coordinates(button_bounds)
        # actions.append(ClickAction(x=x, y=y, is_full_screen=True))
        actions.append(ClickAction(x=x, y=y))
    button_bounds_pattern = rf'<node[^>]*text="完成"[^>]*bounds="([^"]+)"'
    button_bounds_match = re.search(button_bounds_pattern, xml)
    button_bounds = button_bounds_match.group(1) if button_bounds_match else ""
    x, y = parse_coordinates(button_bounds)
    # actions.append(ClickAction(x=x, y=y, is_full_screen=True))
    actions.append(ClickAction(x=x, y=y))

    button_bounds_pattern = rf'<node[^>]*text="查询缴费"[^>]*bounds="([^"]+)"'
    button_bounds_match = re.search(button_bounds_pattern, xml)
    button_bounds = button_bounds_match.group(1) if button_bounds_match else ""
    x, y = parse_coordinates(button_bounds)
    # actions.append(ClickAction(x=x, y=y, is_full_screen=True))
    actions.append(ClickAction(x=x, y=y))
    return actions
    # else:
    #     # 不一致 要点击省份框
    #     x, y = parse_coordinates(province_coord)
    #     return [ClickAction(x=x, y=y, is_full_screen=True)]


